# Actual finite native radar job, owned sensor and guarded keyboard consumer.
param([string]$RepoRoot=(Split-Path $PSScriptRoot -Parent),[Parameter(Mandatory=$true)][string]$CliDir,[string]$DllDir,[string]$Out,[switch]$Baseline,[switch]$CompileOnly)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $RepoRoot).Path)
$CliDir=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $CliDir).Path);if(-not$DllDir){$DllDir=$CliDir};$DllDir=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $DllDir).Path)
if(-not$Out){$Out=Join-Path $repo 'verify/session11_radar/native'};$output=[IO.Path]::GetFullPath($Out);if(-not$output.StartsWith($repo.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Output must remain inside repo'}
$run=Join-Path $output ('run_'+[guid]::NewGuid().ToString('N'));[void](New-Item -ItemType Directory -Force $run,"$run/temp");$env:TEMP="$run/temp";$env:TMP=$env:TEMP
$calls=[Collections.Generic.List[object]]::new();$checks=[Collections.Generic.List[object]]::new();$cases=[Collections.Generic.List[object]]::new();$arches=[Collections.Generic.List[object]]::new();$pins=[Collections.Generic.List[object]]::new();$actors=[Collections.Generic.List[object]]::new();$pending=[Collections.Generic.List[object]]::new();$current=$null;$serial=0;$controlToken=0;$complete=$false;$sourceStable=$false;$problem=$null;$owner='radar-'+[guid]::NewGuid().ToString('N')
function Check([bool]$Good,[string]$Name){$checks.Add(@{pass=$Good;name=$Name});Write-Host "$(if($Good){'PASS'}else{'FAIL'}) $Name"}
function Require([bool]$Good,[string]$Name){if(-not$Good){throw $Name}}
function Pin([string]$Path){$pins.Add(@{path=$Path;sha256=(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash})}
. "$PSScriptRoot/vi_r1_identity.ps1"
. "$PSScriptRoot/_vcvars.ps1";$vcDir=Get-VcVarsDir
if(-not('ViWndProcAwTail'-as[type])){Add-Type -Path "$repo/test/vi_r1_tail.cs"}
if(-not('ViR2Pipe'-as[type])){Add-Type -Path "$repo/test/vi_r2_pipe.cs"}
if(-not('ViRadarPending'-as[type])){Add-Type -Path "$repo/test/vi_radar_pipe.cs"}
# Reuse the reviewed fixture-only job implementation without executing its suite.
$jobFile=Join-Path $PSScriptRoot 'run_suitecontracttest.ps1';Pin $jobFile
if(-not('ViSuiteContractJobV1'-as[type])){$jobSource=Get-Content -LiteralPath $jobFile -Raw;$first=$jobSource.IndexOf('using System;');$last=$jobSource.IndexOf("'@}",$first);if($first-lt0-or$last-le$first){throw 'reviewed job helper extraction failed'};Add-Type $jobSource.Substring($first,$last-$first)}
$gateScript=Join-Path $run 'owned_native_gate.ps1'
[IO.File]::WriteAllText($gateScript,@'
param([string]$GateName,[string]$Image,[string]$ArgumentFile)
$ErrorActionPreference='Stop';$gate=[Threading.EventWaitHandle]::OpenExisting($GateName)
try{if(-not$gate.WaitOne(10000)){throw 'owned native gate not released'}}finally{$gate.Dispose()}
$nativeArguments=@(Get-Content -LiteralPath $ArgumentFile -Raw|ConvertFrom-Json)
& $Image @nativeArguments
exit $LASTEXITCODE
'@)
function RunOwned([string]$image,[string[]]$arguments,[int]$budget,[string]$label){
 $script:serial++;$label=[string]$serial+'_'+$label;$name='Local\vinput_native_radar_'+[guid]::NewGuid().ToString('N');$gate=[Threading.EventWaitHandle]::new($false,[Threading.EventResetMode]::ManualReset,$name);$job=[ViSuiteContractJobV1]::new();$p=$null;$started=$false;$stdout=$null;$stderr=$null;$counts=$null;$errorText=$null;$timeout=$false;$watch=[Diagnostics.Stopwatch]::StartNew()
 $argFile=Join-Path $run ($label+'.arguments.json');ConvertTo-Json -InputObject @($arguments)|Set-Content -LiteralPath $argFile
 try{
  $si=[Diagnostics.ProcessStartInfo]::new((Get-Command pwsh).Source);$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true
  foreach($arg in @('-NoProfile','-File',$gateScript,'-GateName',$name,'-Image',$image,'-ArgumentFile',$argFile)){[void]$si.ArgumentList.Add($arg)}
  $p=[Diagnostics.Process]::new();$p.StartInfo=$si;[void]$p.Start();$started=$true;$stdout=[ViWndProcAwTail]::new($p.StandardOutput);$stderr=[ViWndProcAwTail]::new($p.StandardError);$job.Assign($p,$si.FileName);[void]$gate.Set();$timeout=-not$p.WaitForExit($budget)
 }catch{$errorText=$_.Exception.Message}
 finally{
  try{$counts=$job.Counts();if($counts[1]-gt0){$job.Terminate()};$end=[Environment]::TickCount64+5000;do{$counts=$job.Counts();if($counts[1]-eq0){break};Start-Sleep -Milliseconds 25}while([Environment]::TickCount64-lt$end);if($counts[1]-ne0){throw 'owned native job did not become empty'};if($started-and-not$p.WaitForExit(2000)){throw 'original gated process did not exit'}}catch{$errorText=(@($errorText,$_.Exception.Message)|Where-Object{$_})-join'; '}
  if($started-and-not$p.HasExited){try{$p.Kill();[void]$p.WaitForExit(2000)}catch{$errorText=(@($errorText,$_.Exception.Message)|Where-Object{$_})-join'; '}}
  $drains=$true;foreach($task in @($stdout,$stderr)){if($task){try{$null=$task.Wait(3000);if(-not$task.Complete-or$task.Error-or$task.Characters-gt65536){$drains=$false}}catch{$drains=$false}}}
  $r=@{label=$label;exit=$(if($started-and$p.HasExited){$p.ExitCode}else{$null});stdout=$(if($stdout){$stdout.Text()}else{''});stderr=$(if($stderr){$stderr.Text()}else{''});elapsed_ms=$watch.ElapsedMilliseconds;timeout=$timeout;budget_ms=$budget;job_active_final=$(if($counts){$counts[1]}else{$null});drains_completed=$drains;identity=@{pid=$job.RootPid;created_filetime=$job.CreatedFiletime;image=$job.Image};error=$errorText}
  $calls.Add($r);$r.stdout|Set-Content -LiteralPath (Join-Path $run ($label+'.stdout.log'));$r.stderr|Set-Content -LiteralPath (Join-Path $run ($label+'.stderr.log'));$job.Dispose();$gate.Dispose();if($p){$p.Dispose()}
 }
 if($timeout-or$errorText-or-not$drains){throw "owned $label failed or exceeded finite budget: $errorText"};return $r
}
function Rows([string]$Path){if(Test-Path -LiteralPath $Path){foreach($line in ((Get-Content -LiteralPath $Path -Raw)-split'\r?\n')){if($line.StartsWith('{')-and$line.EndsWith('}')){$line|ConvertFrom-Json}}}}
function Live{Require ($current-and(ReadRetainedImage $current.process $current.path $current.created $current.retained).matched) 'fresh exact retained kernel fixture identity'}
function Background{Live;[uint32]$pidValue=0;$foreground=[ViWndProcAwNative]::GetForegroundWindow();[void][ViWndProcAwNative]::GetWindowThreadProcessId($foreground,[ref]$pidValue);Require ($pidValue-ne$current.pid) 'independent actual foreground outside fixture';return $foreground.ToInt64()}
function Control([uint32]$Action){
 Live;$h=[IntPtr]::new([long][uint64]$current.ready.hwnd);[uint32]$pidValue=0;Require ([ViWndProcAwNative]::GetWindowThreadProcessId($h,[ref]$pidValue)-eq$current.ready.thread-and$pidValue-eq$current.pid) 'exact own HWND/thread for private control';$script:controlToken++;$token=$controlToken
 Require ([ViWndProcAwNative]::PostMessageW($h,0x80B9,[UIntPtr]::new([uint64]$Action),[IntPtr]::new([long]$token))) 'own control accepted';$until=[Environment]::TickCount64+3500
 do{$ack=@(Rows $current.log|Where-Object {$_.event-eq'control'-and$_.token-eq$token})|Select-Object -Last 1;if($ack){Require ($ack.ok-is[bool]-and$ack.ok) 'typed exact tokened control acknowledgement';$snapshot=@(Rows $current.log|Where-Object {$_.event-eq'snapshot'-and$_.token-eq$token})|Select-Object -Last 1;Require ($null-ne$snapshot) 'independent consumer snapshot';return $snapshot};if($current.process.HasExited){throw 'fixture exited before own control acknowledgement'};Start-Sleep -Milliseconds 5}while([Environment]::TickCount64-lt$until);throw 'bounded private control acknowledgement unavailable'
}
function InvokeRadarCli([string[]]$Arguments){Live;$r=RunOwned $current.cli (@('--json','--pid',[string]$current.pid,'--owner',$owner)+$Arguments) 10000 'cli';$lines=@($r.stdout-split'\r?\n'|Where-Object {$_-match'\S'});Require ($lines.Count-eq1) 'exact one chosen CLI JSON reply';$r.reply=$lines[0]|ConvertFrom-Json;return $r}
function Wire([hashtable]$Object,[int]$Budget=2500){Live;if(-not$Object.ContainsKey('owner')){$Object.owner=$owner};$request=$Object|ConvertTo-Json -Compress -Depth 10;$p=[ViRadarPending]::Start([uint32]$current.pid,$current.retained,$current.created,$current.path,$request,$Budget);try{$watch=[Diagnostics.Stopwatch]::StartNew();$wire=$p.Finish($Budget+200);$row=@{request=$request;text=$wire.Text;complete=$wire.Complete;server_pid=$wire.ServerPid;error=$wire.Error;elapsed_ms=$watch.ElapsedMilliseconds};$calls.Add($row);Require ($wire.Complete-and$wire.ServerPid-eq$current.pid-and-not$wire.Error) 'finite exact owned native pipe reply';$row.reply=$wire.Text|ConvertFrom-Json;Require ($row.reply.ok-is[bool]) 'typed native result';return $row.reply}finally{$p.Dispose()}}
function StartFixture([string]$Image,[string]$CliPath,[string]$Dll,[string]$Name){
 $gateName='Local\vinput_radar_actor_'+[guid]::NewGuid().ToString('N');$gate=[Threading.EventWaitHandle]::new($false,[Threading.EventResetMode]::ManualReset,$gateName);$job=[ViSuiteContractJobV1]::new();$p=[Diagnostics.Process]::new();$log=Join-Path $run ($Name+'.jsonl');$t=@{process=$p;path=$Image;pid=0;created=[long]0;retained=[long]0;job=$job;gate=$gate;log=$log;cli=$CliPath;dll=$Dll;arch=$Name.Split('.')[0];batchCases=0;assigned=$false;cleanup=$null};$actors.Add($t);$script:current=$t
 $si=[Diagnostics.ProcessStartInfo]::new($Image);$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.Environment['TEMP']="$run/temp";$si.Environment['TMP']="$run/temp";[void]$si.ArgumentList.Add($log);[void]$si.ArgumentList.Add($gateName);$p.StartInfo=$si;Require ($p.Start()) 'owned actor starts behind private gate';$t.pid=$p.Id;$t.retained=$p.Handle.ToInt64();$t.created=$p.StartTime.ToUniversalTime().Ticks
