 do{$ready=@(Rows $log|Where-Object event -eq ready)|Select-Object -First 1;if($ready-or$p.HasExited){break};Start-Sleep -Milliseconds 10}while([Environment]::TickCount64-lt$until)
 $guard=@(Rows $log|Where-Object event -eq guards)|Select-Object -First 1;$t.ready=$ready;Require ($ready-and$ready.pid-eq$t.pid-and$ready.actual_offscreen_checked-and$guard.safe-and$guard.terminal_desktop_writers-eq19-and$guard.lower_keys-eq'fabricated all up'-and$guard.lower_focus-eq'fabricated outside/null'-and-not$guard.native_writer_called-and-not$guard.native_printwindow_called) 'actual terminal/fabricated/offscreen prerequisites before chosen DLL';$t.foreground=Background;$before=Control 0;Require ($before.mask-eq0-and$before.gks_mask-eq0-and$before.gkbs_mask-eq0-and$before.gkbs_ok) 'fabricated lower readers independently all released'
 $injection=InvokeRadarCli @('inject','--dll',$Dll,'--hooks-only');Require ($injection.exit-eq0-and$injection.reply.ok) 'real chosen product DLL injects';$configured=Wire @{cmd='config';hwnd=('0x{0:X}'-f[uint64]$ready.hwnd);fakefocus=$true;autoactivate=$false;blockfocus=$true;isolate=$true;msgs='on'};Require ($configured.ok-and$configured.msgmode-eq1) 'exact current actor adopted with explicit messages'
 $readiness=InvokeRadarCli @('readiness');Require ($readiness.exit-eq0-and$readiness.reply.ok-and$readiness.reply.hook_ready-and$readiness.reply.window_ready-and$readiness.reply.queue_ready) 'fresh actual full queue readiness';$neutral=Control 0;Require ($neutral.mask-eq0-and$neutral.gks_mask-eq0-and$neutral.gkbs_mask-eq0) 'injected virtual readers initially released';$t.writerBaseline=$neutral.terminal_calls;return $t
}
function StopFixture{
 foreach($p in @($pending)){try{$p.Dispose()}catch{}};$pending.Clear();if(-not$current){return};$t=$current;$errorText=$null;$counts=$null
 try{if($t.assigned){try{if(-not$t.process.HasExited){try{$jobs=Wire @{cmd='jobs'};foreach($j in @($jobs.jobs)){if($j.owner-eq$owner-and-not$j.job_complete){$null=Wire @{cmd='job-cancel';id=$j.job_id}}};foreach($key in @('w','a','d','j')){$null=Wire @{cmd='up';key=$key}};$null=Control 98;[void]$t.process.WaitForExit(800)}catch{}};$counts=$t.job.Counts();if($counts[1]-gt0){$t.job.Terminate()};$until=[Environment]::TickCount64+5000;do{$counts=$t.job.Counts();if($counts[1]-eq0){break};Start-Sleep -Milliseconds 25}while([Environment]::TickCount64-lt$until);Require ($counts[1]-eq0-and$t.process.WaitForExit(2000)) 'owned actor plus descendants bounded cleanup'}catch{$errorText=$_.Exception.Message}}else{if($t.retained-and(ReadRetainedImage $t.process $t.path $t.created $t.retained).matched){$t.process.Kill();Require ($t.process.WaitForExit(2000)) 'original gated actor cleanup before assignment'}}}
 finally{$t.cleanup=@{active_final=$(if($counts){$counts[1]}else{$null});original_exited=$(try{$t.process.HasExited}catch{$false});identity=@{pid=$t.pid;created=$t.created;image=$t.path;retained_handle=$t.retained};error=$errorText};$t.job.Dispose();$t.gate.Dispose();$t.process.Dispose();$t.Remove('process');$t.Remove('job');$t.Remove('gate');$script:current=$null}
}
function Snapshot{$s=Control 0;return @{snapshot=$s;keys=@(Rows $current.log|Where-Object {$_.event-eq'key_snapshot'-and$_.token-eq$s.token})}}
function Key($Snapshot,[int]$Vk){return @($Snapshot.keys|Where-Object vk -eq $Vk)|Select-Object -Last 1}
function Released([string]$Name,[int]$Expected=0){$s=Snapshot;$n=Wire @{cmd='status'};$s.native_virtual_down=$n.virtual_down;$s.foreground_before=$current.caseForeground;$s.foreground_after=Background;$s.foreground_unchanged=$s.foreground_after-eq$s.foreground_before;$s.invalidated_measurement=if($s.foreground_unchanged){$null}else{'actual_foreground_changed_during_case; attribution UNKNOWN'};$expectedKeys=if($Expected-eq8){@(74)}else{@()};Check ($s.snapshot.mask-eq$Expected-and$s.snapshot.gks_mask-eq$Expected-and$s.snapshot.gkbs_mask-eq$Expected-and$s.snapshot.gkbs_ok-and-not$s.snapshot.a_d_overlap-and$s.snapshot.records_dropped-eq0-and$s.snapshot.terminal_calls-eq$current.writerBaseline-and(@($n.virtual_down|Where-Object {$_-in@(87,65,68,74)})-join',')-eq($expectedKeys-join',')-and$s.foreground_unchanged) "$Name exact owned release; independent GAKS/GKS/GKBS, no A+D overlap, no extra terminal calls and unchanged actual foreground";return $s}
function Radar([bool]$Turn=$false,[hashtable]$Options=@{}){$r=@{cmd=$(if($Turn){'radar-turn'}else{'radar-nav'});request_id=[guid]::NewGuid().ToString('N');radar_mode='heading_up';radar_region='100,100,128,128';colour_r=0;colour_g=255;colour_b=0;colour_tolerance=0;min_pixels=9;max_pixels=9;timeout_ms=4500;poll_ms=50;progress_ms=1000;period_ms=100;stable_samples=3;arrival_radius=6;angle_tolerance=6;forward_cone=18};if($Turn){$r.degrees=45};foreach($key in $Options.Keys){$r[$key]=$Options[$key]};return $r}
